// Ταυτότητα & προσωπικότητα του βοηθού.
// Ο χρήστης διαλέγει όνομα + φύλο (όπως η Siri). Ο βοηθός νιώθει σαν Έλληνας
// άνθρωπος-ειδικός στα ακίνητα: ζεστός, έξυπνος, με γνώμη, αλλά παραπέμπει
// πάντα στον σωστό επαγγελματία/φορέα για δεσμευτικά θέματα.
// ═══════════════════════════════════════════════════════════════════════════

export type Gender = 'female' | 'male' | 'nonbinary' | 'neutral';

export interface AssistantIdentity {
  name: string;
  gender: Gender;
  memory: boolean;    // να θυμάται τις συζητήσεις
  compare: boolean;   // να συγκρίνει μεταξύ ακινήτων
  formal: boolean;    // true = πληθυντικός ευγενείας (εσείς), false = ενικός (εσύ)
}

export const DEFAULT_IDENTITY: AssistantIdentity = { name: 'Άριελ', gender: 'neutral', memory: true, compare: false, formal: false };

